#include <torch/library.h>
#include <torch/csrc/autograd/custom_function.h>
#include "pytorch_npu_helper.hpp"
#include <torch/extension.h>

at::Tensor gather_custom_impl_npu(const at::Tensor& x, const at::Tensor& idx) {
    at::Tensor y = at::empty_like(idx, x.options()); // 输出形状与idx一致，dtype与x一致
    EXEC_NPU_CMD(aclnnGatherCustom, x, idx.to(at::kInt), y);
    return y;
}

TORCH_LIBRARY_IMPL(myops, PrivateUse1, m) {
    m.impl("gather_custom", &gather_custom_impl_npu);
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("gather_custom", &gather_custom_impl_npu, "row-wise gather along dim=1");
}
